// Smash Remix 2.0.1: "stages-dream-land" game option (server only)
//
// GENERATED by smash-remix-2.0.1-gen-stage-options.py from the ROM; edit the
// stage list there and regenerate. Ranked stages, as the ranked module set
// them up (SmashRemix.cpp, stage list kVanillaStages):
//   0x06 Dream Land               hazard mode 0
// Stage select is off: every game is on the stage above. When a match starts
// without stage select, Remix picks from Random's stage list
// (Stages.swap_stage_), which holds only this stage.
// Each pick applies the stage's hazard mode from Stages.tournament_hazard_mode_table
// (hovering a stage on the tournament layout, or Random's pick).
//
// Needs ranked-rules (tournament layout, and this option's boot code sits in the body of Toggles.settings_shortcut, which ranked-rules makes unreachable).
//
// Assemble over a copy of the ROM to check the JSON (see smash-remix-2.0.1-ranked-rules.asm):
//   bass.exe -o patched.z64 smash-remix-2.0.1-stages-dream-land.asm
//
// ROM: Smash_Remix_2.0.1.z64, MD5 2B2D6B295106C54216B7FC7A2F14346E.

arch n64.cpu
endian msb

constant r0(0)
constant t0(8)

macro seek(variable ram) {
    origin ram - 0x80400000 + 0x02C00000
    base ram
}
macro seek_logo(variable ram) {
    origin ram - 0x7FFB2E40
    base ram
}
macro toggle(variable entry, variable value) {
    seek(entry + 4)
    dw value
}

// ---------------------------------------------------------------------------
// 1. Stage select off
//
// mnStartupFuncStart (N64 logo scene start, 0x80131CB8) calls
// gcMakeDefaultCameraGObj once, after scManagerRunLoop has set up the VS
// battle state and before the CSS first opens. Call stage_boot_init instead;
// it turns stage select off in the battle state (the CSS reads
// is_stage_select when a match starts, mnPlayersVSFuncRun) and jumps on with
// a0-a3 untouched. Only the VS options menu changes it otherwise, and
// ranked-rules makes that unreachable.
constant gcMakeDefaultCameraGObj(0x8000B9FC)
constant stage_boot_init(0x8046F080)    // settings_shortcut body, this option's words
seek_logo(0x80131D44)
    jal     stage_boot_init                 // was: jal gcMakeDefaultCameraGObj (0x0C002E7F); delay slot (addiu a3, r0, 2) kept
seek(stage_boot_init)
    lui     t0, 0x800A
    j       gcMakeDefaultCameraGObj
    sb      r0, 0x4D12(t0)                  // gSCManagerTransferBattleState (0x800A4D08) +0x0A is_stage_select = off

// VsRemixMenu.global_stage_select: restored into the battle state when the CSS
// is left for the VS menu (blocked by ranked-rules). Off, as the module set it.
seek(0x804F757C)
    dw 0                                    // was: 1

// Toggles.entry_hazard_mode is already 0, this stage's hazard mode.
// Random's pick sets the hazard toggle from Stages.tournament_hazard_mode_table on
// the tournament layout; its entry for 0x06 is already 0.

